-- CAUSE: semilla reproducible para usuarios david (20) y jacobo (21).
-- Sin credenciales ni hashes. Usa exclusivamente tablas y categorías existentes.
-- Por usuario: 33 ingresos, 97 gastos, 6 presupuestos, 3 metas, 9 aportes, 3 pagos recurrentes y alertas.
-- El esquema no implementa cuentas bancarias ni transferencias explícitas; aportes son el ahorro interno.
SET @david_id := (SELECT id FROM users WHERE id=20 AND name='david');
SET @jacobo_id := (SELECT id FROM users WHERE id=21 AND name='jacobo');
START TRANSACTION;
DELETE FROM alerts WHERE user_id IN (@david_id,@jacobo_id);
DELETE FROM recurring_payments WHERE user_id IN (@david_id,@jacobo_id);
DELETE FROM goal_contributions WHERE user_id IN (@david_id,@jacobo_id);
DELETE FROM budgets WHERE user_id IN (@david_id,@jacobo_id);
DELETE FROM financial_transactions WHERE user_id IN (@david_id,@jacobo_id);
DELETE FROM savings_goals WHERE user_id IN (@david_id,@jacobo_id);
SET @jacobo_rent_id := (SELECT id FROM recurring_payments WHERE user_id=@jacobo_id AND name='Arriendo programado' LIMIT 1);
SET @jacobo_internet_id := (SELECT id FROM recurring_payments WHERE user_id=@jacobo_id AND name='Internet y servicios' LIMIT 1);
SET @jacobo_streaming_id := (SELECT id FROM recurring_payments WHERE user_id=@jacobo_id AND name='Suscripción de entretenimiento' LIMIT 1);
SET @david_rent_id := (SELECT id FROM recurring_payments WHERE user_id=@david_id AND name='Arriendo programado' LIMIT 1);
SET @david_internet_id := (SELECT id FROM recurring_payments WHERE user_id=@david_id AND name='Internet y servicios' LIMIT 1);
SET @david_streaming_id := (SELECT id FROM recurring_payments WHERE user_id=@david_id AND name='Suscripción de entretenimiento' LIMIT 1);
COMMIT;
